# Find the names of students who did NOT take any courses from the 'Biology' department.
# We filter the 'students' collection. For each student, we check their 'take' (courses taken).
# We use HASNOT to ensure that none of their taken courses are from the 'Biology' department.
students_no_biology_courses = students.WHERE(
    HASNOT(take.WHERE(
        course.dept_name == 'Biology'
    )) == 1
).CALCULATE(
    student_name=name
)

most_common_characteristic = product_characteristic.CALCULATE(
    char_name=characteristic.characteristic_name
).PARTITION(
    name="char_groups",
    by=(char_name)
).CALCULATE(
    characteristic_name=char_name,
    occurrence_count=COUNT(product_characteristic)
).TOP_K(1, by=occurrence_count.DESC()).CALCULATE(
    name=characteristic_name
)

bike_most_traveled_in_zip = trips.WHERE(
    zip_code == 94002
).PARTITION(
    name="bike_trips_group",
    by=bike_id
).CALCULATE(
    bike_id = bike_id,
    num_trips = COUNT(trips)
).TOP_K(1, by=num_trips.DESC()).CALCULATE(bike_id=bike_id)

result = shops.CALCULATE(
    shop_name=shop_name, # Get the name of the shop
    total_quantity=SUM(stocks.quantity) # Calculate the total quantity for each shop by summing quantities in its 'stocks' sub-collection
).TOP_K(
    1, # Get only the top 1 shop
    by=total_quantity.DESC() # Order by total_quantity in descending order to find the greatest
).CALCULATE(
    shop_name=shop_name # Select only the shop_name as the final output
)

most_papers_inst = insts.CALCULATE(
    num_papers=COUNT(authorships.paper)
).TOP_K(1, by=num_papers.DESC()).CALCULATE(
    institution_name=name
)

drivers_in_both_races = formula_1.result.PARTITION(
    name="driver_race_entries", by=driverid
).WHERE(
    (HAS(driver_race_entries.WHERE(race.name == "Australian Grand Prix")) > 0) &
    (HAS(driver_race_entries.WHERE(race.name == "Chinese Grand Prix")) > 0)
).CALCULATE(
    driver_id=driverid,
    forename=MIN(driver_race_entries.driver.forename)
)

party_delegates = elections.CALCULATE(
    party_name=party_join.party
).PARTITION(
    name="party_groups",
    by=(party_name)
).CALCULATE(
    party_name=party_name,
    num_delegates=COUNT(elections)
).TOP_K(1, by=num_delegates.DESC())

most_popular_scholarship_sport = sportsinfos.WHERE(
    onscholarship == 'Yes'
).PARTITION(
    name="sports_groups", by=sportname
).CALCULATE(
    sport_name=sportname,
    num_students_on_scholarship=COUNT(sportsinfos)
).TOP_K(1, by=num_students_on_scholarship.DESC())
